def _repr(self):
    fields = ', '.join(f'{k}={v!r}' for k, v in vars(self).items())
    return f'{self.__class__.__name__}({fields})'

def auto_repr(cls):
    cls.__repr__ = _repr
    return cls

@auto_repr
class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y

Point(1, 2)    # Point(x=1, y=2)
```
_repr بیرون است چون متغیر آزاد ندارد (closure نیست) و نباید هر بار decorate کردن دوباره ساخته شود.
